562		fmt.Println("CaseDock - 客服工单与知识服务")
563		fmt.Println("Usage: go run . serve [--host ADDRESS] [--port PORT] [--data-dir DIRECTORY]")
564		fmt.Println("       go run . --help")
565		fmt.Println("Defaults: --host 127.0.0.1 --port 8080 --data-dir data")
566	}
