listArea.addEventListener("click", function(ev){
  var btn = ev.target.closest("button[data-i]");
  if (!btn) return;
  showDetail(loaded[Number(btn.getAttribute("data-i"))]);
});

function row(k){
  return '<dt>' + escapeHtml(k) + '</dt><dd></dd>';
}
// 每次打开详情都会创建独立的视图对象，输入内容、提示、按钮状态与操作标识都从属于它。
// 分派提交时锁定自己的视图；结果返回后只有该视图仍是当前视图时才回写详情，
// 保证迟到的结果始终归属于提交时的工单，不影响用户正在查看或准备分派的另一张工单。
var view = null;
var viewSeq = 0;

function setViewNotice(v, kind, text){
  var n = v.notice;
  if (!n) return;
  n.className = "notice " + kind;
  n.textContent = text; // 以文本节点显示，不执行其中的页面代码
}

function showDetail(t){
  view = {
    seq: ++viewSeq,
    ticket: t,
    opId: newSubmitId() // 每次打开详情开始一次新的分派操作
  };
  detail.innerHTML =
    '<button type="button" class="secondary close">关闭</button>' +
    "<h3>工单详情</h3><dl>" +
    row("编号") + row("状态") + row("负责人") +
    row("优先级") + row("来源") + row("类别") +
    row("问题描述") + row("联系人") + row("联系方式") +
    row("关联订单号") + row("附件说明") +
    row("创建时间") + row("最近处理时间") +
    "</dl>" +
    "<h4>分派记录</h4>" +
    '<div class="assign-history"></div>' +
    "<h4>分派负责人</h4>" +
    '<form id="assign-form" novalidate>' +
    '<input type="text" id="f-assignee" placeholder="填写负责人姓名" autocomplete="off">' +
    '<div class="actions"><button type="submit" id="assign-btn">提交分派</button></div>' +
    '<div id="assign-notice" class="notice" role="alert"></div>' +
    "</form>";
  fillDetail(t);
  // 缓存属于本视图的表单元素，回调只操作这些元素，不按 id 查找当前详情
  view.input = document.getElementById("f-assignee");
  view.btn = document.getElementById("assign-btn");
  view.notice = document.getElementById("assign-notice");
  detail.classList.add("open");
  detail.setAttribute("aria-hidden","false");
  detail.scrollIntoView({behavior:"smooth", block:"nearest"});
}

// fillDetail 只更新详情中的取值与分派记录，不动分派表单与提示。
function fillDetail(t){
  var map = {
    "编号": t.id, "状态": t.status, "负责人": t.assignee,
    "优先级": t.priority, "来源": t.source, "类别": t.category,
    "问题描述": t.description, "联系人": t.contactName, "联系方式": t.contactInfo,
    "关联订单号": t.orderNumber || "（无）", "附件说明": t.attachmentNote || "（无）",
    "创建时间": fmtTime(t.createdAt), "最近处理时间": fmtTime(t.updatedAt)
  };
  var dts = detail.querySelectorAll("dl dt");
  for (var i=0;i<dts.length;i++){
    // 以文本节点写入，换行由 CSS white-space:pre-wrap 保留
    dts[i].nextElementSibling.textContent = map[dts[i].textContent];
  }
  var hist = detail.querySelector(".assign-history");
  var recs = Array.isArray(t.assignments) ? t.assignments : [];
  if (!recs.length) {
    hist.innerHTML = '<p class="empty">暂无分派记录。</p>';
    return;
  }
  var html = '<ul class="assign-list">';
  recs.forEach(function(rec){ // 按发生顺序展示，姓名按普通文字显示
    html += "<li>" + escapeHtml(rec.from) + " → " + escapeHtml(rec.to) +
      ' <span class="assign-time">' + escapeHtml(fmtTime(rec.at)) + "</span></li>";
  });
  html += "</ul>";
  hist.innerHTML = html;
}

detail.addEventListener("submit", function(ev){
  if (!ev.target || ev.target.id !== "assign-form") return;
  ev.preventDefault();
  var v = view;
  if (!v) return;
  var input = v.input;
  var btn = v.btn;
  var assignee = input.value.trim();
  if (!assignee) {
    setViewNotice(v, "err", "请填写负责人。");
    return;
  }
  if (assignee === "未分派") {
    setViewNotice(v, "err", "负责人不能填写“未分派”。");
    return;
  }
  setViewNotice(v, "", "");
  // pending 只锁定本视图自己的按钮；切换到的另一张工单有它自己的视图与按钮状态
  v.pending = true;
  btn.disabled = true;
  btn.textContent = "正在分派…";
  var targetId = v.ticket.id;
  fetch("/api/tickets/" + encodeURIComponent(targetId) + "/assignment", {
    method: "POST",
    headers: {"Content-Type": "application/json"},
    body: JSON.stringify({assignee: assignee, operationId: v.opId})
  }).then(function(resp){
    return resp.json().catch(function(){ return {}; }).then(function(data){
      return {status: resp.status, data: data};
    });
  }).then(function(r){
    if (r.status === 200 && r.data && r.data.ticket) {
      var nt = r.data.ticket;
      for (var i=0;i<loaded.length;i++){ // 列表立即显示新负责人与本次处理时间
        if (loaded[i].id === nt.id) { loaded[i] = nt; break; }
      }
      renderList();
      if (view === v) { // 用户仍停留在提交时的详情：成功结果只写回这一个视图
        v.ticket = nt;
        fillDetail(nt);
        v.opId = newSubmitId(); // 本次操作已成功，下一次分派使用新标识
        input.value = "";
        setViewNotice(v, "ok", r.data.changed ? "分派成功，负责人：" + nt.assignee : "负责人未变化");
      }
    } else {
      // 失败结果只属于提交时的视图，不能覆盖另一张工单自身的提示或等待状态
      var msg;
      if (r.status === 400) {
        msg = "输入错误：" + (r.data.error || "请检查填写内容") +
          "\n填写内容已保留，可修改后重试。";
      } else if (r.status === 404) {
        msg = "工单不存在：" + (r.data.error || targetId) +
          "\n请刷新列表后重试。";
      } else if (r.status === 409) {
        msg = "操作标识冲突：" + (r.data.error || "同一操作标识对应了不同负责人") +
          "\n记录未改动。请关闭详情后重新打开再分派。";
      } else {
        msg = "分派失败（HTTP " + r.status + "）：" + (r.data.error || "未知错误") +
          "\n填写内容已保留，请重试。";
      }
      if (view === v) {
        setViewNotice(v, "err", msg); // 填写内容原样保留，操作标识不变，可直接重试
      }
    }
  }).catch(function(){
    var netMsg = "分派失败：无法连接服务。填写内容已保留，请稍后重试。";
    if (view === v) {
      setViewNotice(v, "err", netMsg);
    }
  }).finally(function(){
    // 只恢复提交时视图自己的按钮；另一张工单的等待状态不由本次结果解除
    v.pending = false;
    btn.disabled = false;
    btn.textContent = "提交分派";
  });
});
detail.addEventListener("click", function(ev){
  if (ev.target.classList.contains("close")) {
    // 关闭详情不取消已提交的分派；其结果只更新列表数据，不重新打开详情
    view = null;
    detail.classList.remove("open");
    detail.setAttribute("aria-hidden","true");
    detail.innerHTML = "";
  }
});

function loadTickets(){
  return fetch("/api/tickets", {headers:{"Accept":"application/json"}})
    .then(function(resp){
      if (!resp.ok) throw new Error("HTTP " + resp.status);
      return resp.json();
    })
    .then(function(data){
      var arr = Array.isArray(data.tickets) ? data.tickets : [];
      loaded = arr; // 只有读取成功才替换，失败时保留原列表
      renderList();

