// 端到端验证：分派请求在途时切换/关闭详情，迟到结果必须始终归属提交时的工单。
const CDP_PORT = 9333;
const BASE = "http://127.0.0.1:8899";

async function cdpTargets() {
  const r = await fetch(`http://127.0.0.1:${CDP_PORT}/json/list`);
  return r.json();
}
function connect(wsUrl) {
  const ws = new WebSocket(wsUrl);
  let nextId = 1;
  const pending = new Map();
  const handlers = new Set();
  ws.addEventListener("message", (ev) => {
    const msg = JSON.parse(ev.data);
    if (msg.id && pending.has(msg.id)) {
      const { resolve, reject } = pending.get(msg.id);
      pending.delete(msg.id);
      if (msg.error) reject(new Error(msg.error.message)); else resolve(msg.result);
    } else if (msg.method) {
      handlers.forEach((h) => h(msg.method, msg.params));
    }
  });
  return new Promise((resolve) => {
    ws.addEventListener("open", () => {
      resolve({
        send(method, params = {}) {
          const id = nextId++;
          ws.send(JSON.stringify({ id, method, params }));
          return new Promise((res, rej) => pending.set(id, { resolve: res, reject: rej }));
        },
        on(h) { handlers.add(h); },
        close() { ws.close(); }
      });
    });
  });
}

const targets = await cdpTargets();
const page0 = targets.find((t) => t.type === "page");
const cdp = await connect(page0.webSocketDebuggerUrl);
await cdp.send("Page.enable");
await cdp.send("Runtime.enable");
// 挂起所有分派请求，由测试决定放行/伪造响应/判定失败
await cdp.send("Fetch.enable", { patterns: [{ urlPattern: "*assignment", requestStage: "Request" }] });

const paused = new Map(); // 工单编号 -> requestId
const pausedQueue = [];
cdp.on((method, p) => {
  if (method === "Fetch.requestPaused") {
    const m = /tickets\/([^/]+)\/assignment/.exec(p.request.url);
    paused.set(m[1], p.requestId);
    pausedQueue.push(m[1]);
  }
});

async function evaljs(expr) {
  const r = await cdp.send("Runtime.evaluate", {
    expression: `(function(){${expr}})()`,
    returnByValue: true,
    awaitPromise: true,
  });
  if (r.exceptionDetails) throw new Error("JS: " + JSON.stringify(r.exceptionDetails.exception?.description || r.exceptionDetails.text));
  return r.result.value;
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function waitPaused(ids) {
  const want = new Set(ids);
  for (let i = 0; i < 100; i++) {
    if ([...want].every((id) => paused.has(id))) return;
    await sleep(30);
  }
  throw new Error("requests not paused: " + [...want].filter((id) => !paused.has(id)));
}
async function release(id) {
  await waitPaused([id]);
  await cdp.send("Fetch.continueRequest", { requestId: paused.get(id) });
  paused.delete(id);
}
async function fulfill(id, status, obj) {
  await waitPaused([id]);
  await cdp.send("Fetch.fulfillRequest", {
    requestId: paused.get(id),
    responseCode: status,
    responseHeaders: [{ name: "Content-Type", value: "application/json" }],
    body: Buffer.from(JSON.stringify(obj)).toString("base64"),
  });
  paused.delete(id);
}
async function failNet(id) {
  await waitPaused([id]);
  await cdp.send("Fetch.failRequest", { requestId: paused.get(id), errorReason: "Failed" });
  paused.delete(id);
}

await cdp.send("Page.navigate", { url: BASE + "/" });
await sleep(500);

async function state() {
  return evaljs(`
    var d = document.getElementById("detail");
    function dd(k){ var dts=d.querySelectorAll("dl dt"); for (var i=0;i<dts.length;i++){ if(dts[i].textContent===k) return dts[i].nextElementSibling.textContent; } return null; }
    var inp = document.getElementById("f-assignee");
    var btn = document.getElementById("assign-btn");
    var n = document.getElementById("assign-notice");
